#include <stdio.h>
#include <string.h>

int load_notes(const char *path) {
    FILE *f = fopen(path, "r");
    if (f == NULL) { perror(path); return -1; }        /* why it failed. */

    char line[256];
    int count = 0;
    while (fgets(line, sizeof line, f) != NULL) {       /* loop on the result. */
        line[strcspn(line, "\n")] = '\0';
        printf("%d: %s\n", ++count, line);
    }
    int failed = ferror(f);                              /* error, not EOF? */
    if (fclose(f) != 0) failed = 1;
    return failed ? -1 : count;
}

int save_note(const char *path, const char *text) {
    FILE *f = fopen(path, "a");                          /* append: keep old notes. */
    if (f == NULL) return -1;
    int ok = fprintf(f, "%s\n", text) >= 0;
    if (fclose(f) != 0) ok = 0;                          /* flush can fail here. */
    return ok ? 0 : -1;
}
```

| Mode | Effect |
|---|---|
| `"r"`. | read; fails if missing. |
| `"w"`. | write; creates or **truncates**. |
| `"a"`. | append; creates if missing. |
| `"rb"`/`"wb"`. | binary: no newline translation. |

